'use client';

import { useState, useCallback, useEffect } from 'react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { ChevronUp, ChevronDown } from 'lucide-react';
import { useCanvasStore } from '@/lib/store/canvas-store';
import type { TransitionEdgeData, StateNodeData } from '@/lib/types/canvas';
import { formatTransitionLabel } from '@/lib/types/transition';

interface TransitionPropertiesProps {
  edgeId: string;
  data: TransitionEdgeData;
}

export function TransitionProperties({
  edgeId,
  data,
}: TransitionPropertiesProps) {
  const updateTransitionEdge = useCanvasStore((s) => s.updateTransitionEdge);
  const edges = useCanvasStore((s) => s.edges);
  const nodes = useCanvasStore((s) => s.nodes);

  const [event, setEvent] = useState(data.label.event ?? '');
  const [condition, setCondition] = useState(data.label.condition ?? '');
  const [conditionAction, setConditionAction] = useState(
    data.label.conditionAction ?? ''
  );
  const [transitionAction, setTransitionAction] = useState(
    data.label.transitionAction ?? ''
  );

  // Sync state when selection changes
  useEffect(() => {
    setEvent(data.label.event ?? '');
    setCondition(data.label.condition ?? '');
    setConditionAction(data.label.conditionAction ?? '');
    setTransitionAction(data.label.transitionAction ?? '');
  }, [edgeId, data.label]);

  const commitChanges = useCallback(() => {
    updateTransitionEdge(edgeId, {
      label: {
        event: event.trim() || null,
        condition: condition.trim() || null,
        conditionAction: conditionAction.trim() || null,
        transitionAction: transitionAction.trim() || null,
      },
    });
  }, [
    edgeId,
    event,
    condition,
    conditionAction,
    transitionAction,
    updateTransitionEdge,
  ]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        commitChanges();
      }
    },
    [commitChanges]
  );

  const currentEdge = edges.find((e) => e.id === edgeId);
  const sourceNode = currentEdge
    ? nodes.find((n) => n.id === currentEdge.source)
    : undefined;
  const sourceStateName =
    sourceNode?.type === 'stateNode' && sourceNode.data
      ? (sourceNode.data as StateNodeData).stateBlock.name
      : undefined;
  const siblingCount = currentEdge
    ? edges.filter(
        (e) => e.source === currentEdge.source && e.data && !e.data.isDefault
      ).length
    : 0;

  const preview = formatTransitionLabel({
    event: event.trim() || null,
    condition: condition.trim() || null,
    conditionAction: conditionAction.trim() || null,
    transitionAction: transitionAction.trim() || null,
  });

  return (
    <div className="p-4 space-y-4">
      <h3 className="font-semibold text-sm">Transition Properties</h3>

      {/* Preview */}
      <div className="rounded border bg-muted/50 p-2 text-xs font-mono">
        {data.label.event && (
          <span className="font-semibold">{data.label.event}</span>
        )}
        {data.label.condition && (
          <span className="text-blue-500">[{data.label.condition}]</span>
        )}
        {data.label.conditionAction && (
          <span className="text-green-500">
            {'{'}
            {data.label.conditionAction}
            {'}'}
          </span>
        )}
        {data.label.transitionAction && (
          <span className="text-orange-500">
            /{data.label.transitionAction}
          </span>
        )}
        {!data.label.event &&
          !data.label.condition &&
          !data.label.conditionAction &&
          !data.label.transitionAction && (
            <span className="text-muted-foreground italic">
              (unconditional)
            </span>
          )}
      </div>

      <div className="text-[10px] text-muted-foreground bg-muted/30 rounded p-1.5 font-mono">
        Syntax: <span className="font-semibold">event</span>
        <span className="text-blue-500">[condition]</span>
        <span className="text-green-500">{'{action}'}</span>
        <span className="text-orange-500">/transAction</span>
      </div>

      <Separator />

      <div className="space-y-3">
        <div className="space-y-1.5">
          <Label htmlFor="tr-event" className="text-xs">
            Event
          </Label>
          <Input
            id="tr-event"
            value={event}
            onChange={(e) => setEvent(e.target.value)}
            onBlur={commitChanges}
            onKeyDown={handleKeyDown}
            placeholder="e.g. start_btn"
            className="h-8 text-sm font-mono"
          />
        </div>

        <div className="space-y-1.5">
          <Label htmlFor="tr-condition" className="text-xs">
            Condition <span className="text-blue-500">[...]</span>
          </Label>
          <Input
            id="tr-condition"
            value={condition}
            onChange={(e) => setCondition(e.target.value)}
            onBlur={commitChanges}
            onKeyDown={handleKeyDown}
            placeholder="e.g. speed > 100"
            className="h-8 text-sm font-mono"
          />
        </div>

        <div className="space-y-1.5">
          <Label htmlFor="tr-cond-action" className="text-xs">
            Condition Action{' '}
            <span className="text-green-500">{'{...}'}</span>
          </Label>
          <Input
            id="tr-cond-action"
            value={conditionAction}
            onChange={(e) => setConditionAction(e.target.value)}
            onBlur={commitChanges}
            onKeyDown={handleKeyDown}
            placeholder="e.g. counter++"
            className="h-8 text-sm font-mono"
          />
        </div>

        <div className="space-y-1.5">
          <Label htmlFor="tr-action" className="text-xs">
            Transition Action <span className="text-orange-500">/...</span>
          </Label>
          <Input
            id="tr-action"
            value={transitionAction}
            onChange={(e) => setTransitionAction(e.target.value)}
            onBlur={commitChanges}
            onKeyDown={handleKeyDown}
            placeholder="e.g. initMotor()"
            className="h-8 text-sm font-mono"
          />
        </div>
      </div>

      <Separator />

      <div className="space-y-3">
        <div className="space-y-1.5">
          <Label className="text-xs">Priority</Label>
          <div className="flex items-center gap-2">
            <Input
              type="number"
              min={1}
              value={data.priority}
              onChange={(e) => {
                const val = parseInt(e.target.value, 10);
                if (!isNaN(val) && val >= 1) {
                  updateTransitionEdge(edgeId, { priority: val });
                }
              }}
              className="h-8 text-sm w-20"
            />
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={() => {
                if (data.priority > 1) {
                  updateTransitionEdge(edgeId, {
                    priority: data.priority - 1,
                  });
                }
              }}
              disabled={data.priority <= 1}
            >
              <ChevronUp className="h-3 w-3" />
            </Button>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={() => {
                updateTransitionEdge(edgeId, {
                  priority: data.priority + 1,
                });
              }}
            >
              <ChevronDown className="h-3 w-3" />
            </Button>
            <span className="text-[10px] text-muted-foreground">
              {siblingCount > 1
                ? `${data.priority} of ${siblingCount}`
                : 'Lower = first'}
            </span>
          </div>
        </div>

        {data.isDefault && (
          <div className="text-blue-500 font-medium text-xs">
            Default Transition
          </div>
        )}

        <div className="font-mono text-[10px] text-muted-foreground bg-muted/30 rounded p-1.5">
          Full label: {preview}
        </div>
      </div>
    </div>
  );
}

import type { CanvasNode, TransitionEdge } from '../types/canvas';
import type { Variable } from '../types/variable';
import type { StateMachineModel, ModelState, ModelTransition } from '../types/codegen';

/**
 * Convert a C-unsafe name to a safe identifier
 */
function toSafeName(name: string): string {
  return name
    .replace(/[^a-zA-Z0-9_]/g, '_')
    .replace(/^(\d)/, '_$1')
    .replace(/_+/g, '_')
    .toUpperCase();
}

/**
 * Build a StateMachineModel from canvas nodes, edges, and variables
 */
export function buildModel(
  nodes: CanvasNode[],
  edges: TransitionEdge[],
  variables: Variable[],
  projectName: string = 'StateMachine'
): StateMachineModel {
  const stateNodes = nodes.filter((n) => n.type === 'stateNode');
  const defaultTransitionNodes = nodes.filter((n) => n.type === 'defaultTransition');

  // Build states
  const states: ModelState[] = stateNodes.map((node) => {
    const block = node.data.stateBlock;
    const childIds = stateNodes
      .filter((n) => n.data.stateBlock.parentId === node.id)
      .map((n) => n.id);

    return {
      id: node.id,
      name: block.name,
      safeName: toSafeName(block.name),
      parentId: block.parentId,
      decomposition: block.decomposition,
      isDefault: block.isDefault,
      childIds,
      actions: {
        entry: block.actions.entry
          .sort((a, b) => a.order - b.order)
          .map((a) => a.code)
          .filter((c) => c.trim()),
        during: block.actions.during
          .sort((a, b) => a.order - b.order)
          .map((a) => a.code)
          .filter((c) => c.trim()),
        exit: block.actions.exit
          .sort((a, b) => a.order - b.order)
          .map((a) => a.code)
          .filter((c) => c.trim()),
      },
    };
  });

  // Build transitions
  const transitions: ModelTransition[] = edges.map((edge) => {
    // For default transitions, the source is a dot node
    const isDefault = edge.data?.isDefault ?? false;
    const sourceNode = nodes.find((n) => n.id === edge.source);
    let sourceId = edge.source;

    if (sourceNode?.type === 'defaultTransition') {
      // The source of a default transition is really the parent context
      sourceId = edge.source; // Keep as-is, validator will handle
    }

    return {
      id: edge.id,
      sourceId,
      targetId: edge.target,
      event: edge.data?.label.event ?? null,
      condition: edge.data?.label.condition ?? null,
      conditionAction: edge.data?.label.conditionAction ?? null,
      transitionAction: edge.data?.label.transitionAction ?? null,
      priority: edge.data?.priority ?? 0,
      isDefault,
    };
  });

  // Sort transitions by priority
  transitions.sort((a, b) => a.priority - b.priority);

  // Find root states (no parent)
  const rootStateIds = states
    .filter((s) => s.parentId === null)
    .map((s) => s.id);

  // Find the default state (via default transition or isDefault flag)
  let defaultStateId: string | null = null;

  // First check for default transitions pointing to root states
  const defaultTransitions = transitions.filter((t) => t.isDefault);
  for (const dt of defaultTransitions) {
    const targetState = states.find((s) => s.id === dt.targetId);
    if (targetState && targetState.parentId === null) {
      defaultStateId = targetState.id;
      break;
    }
  }

  // Fallback: check isDefault flag
  if (!defaultStateId) {
    const defaultState = states.find((s) => s.isDefault && s.parentId === null);
    if (defaultState) {
      defaultStateId = defaultState.id;
    }
  }

  // Fallback: first root state
  if (!defaultStateId && rootStateIds.length > 0) {
    defaultStateId = rootStateIds[0];
  }

  return {
    name: toSafeName(projectName),
    states,
    transitions,
    variables,
    rootStateIds,
    defaultStateId,
  };
}

import type { Project, AnnotationData } from '../types/project';
import type { Chart } from '../types/chart';
import type { StateBlock } from '../types/state';
import type { Transition } from '../types/transition';
import type {
  CanvasNode,
  TransitionEdge,
  StateNode,
  DefaultTransitionNode,
  AnnotationNode,
  ChartBlockNode,
  SourceBlockNode,
  SinkBlockNode,
  SystemWireEdge,
} from '../types/canvas';
import type { SystemBlock, SystemWire } from '../types/system';
import { DEFAULT_STATE_SIZE } from '../types/state';
import { EMPTY_TRANSITION_LABEL } from '../types/transition';
import { DEFAULT_ANNOTATION_SIZE } from '../utils/constants';

// ─── Chart Serialization ────────────────────────────────────────

/**
 * Serialize canvas state (nodes + edges) back into a Chart's data
 */
export function serializeCanvasToChart(
  chart: Chart,
  nodes: CanvasNode[],
  edges: TransitionEdge[],
  viewport?: { x: number; y: number; zoom: number }
): Chart {
  const states: StateBlock[] = [];
  const transitions: Transition[] = [];
  const annotations: AnnotationData[] = [];

  for (const node of nodes) {
    if (node.type === 'stateNode') {
      states.push({
        ...node.data.stateBlock,
        position: node.position,
        size: {
          width: (node.style?.width as number) ?? DEFAULT_STATE_SIZE.width,
          height: (node.style?.height as number) ?? DEFAULT_STATE_SIZE.height,
        },
      });
    } else if (node.type === 'annotationNode') {
      annotations.push({
        id: node.id,
        content: node.data.content,
        position: node.position,
        size: {
          width: (node.style?.width as number) ?? DEFAULT_ANNOTATION_SIZE.width,
          height: (node.style?.height as number) ?? DEFAULT_ANNOTATION_SIZE.height,
        },
        color: node.data.color,
        image: node.data.image,
        fontSize: node.data.fontSize ?? 14,
      });
    }
  }

  for (const edge of edges) {
    transitions.push({
      id: edge.id,
      sourceStateId: edge.source,
      targetStateId: edge.target,
      sourceHandle: edge.sourceHandle ?? '',
      targetHandle: edge.targetHandle ?? '',
      label: edge.data?.label ?? { ...EMPTY_TRANSITION_LABEL },
      priority: edge.data?.priority ?? 0,
      isDefault: edge.data?.isDefault ?? false,
    });
  }

  return {
    ...chart,
    states,
    transitions,
    annotations,
    ...(viewport ? { viewport } : {}),
  };
}

/**
 * Deserialize a Chart into canvas nodes and edges
 */
export function deserializeChartToCanvas(chart: Chart): {
  nodes: CanvasNode[];
  edges: TransitionEdge[];
} {
  const nodes: CanvasNode[] = [];
  const edges: TransitionEdge[] = [];

  for (const state of chart.states) {
    const stateNode: StateNode = {
      id: state.id,
      type: 'stateNode',
      position: state.position,
      ...(state.parentId
        ? { parentId: state.parentId, extent: 'parent' as const }
        : {}),
      data: {
        stateBlock: state,
        isHighlighted: false,
        isDropTarget: false,
        validationErrors: [],
      },
      style: {
        width: state.size.width,
        height: state.size.height,
      },
    };
    nodes.push(stateNode);
  }

  for (const transition of chart.transitions) {
    if (transition.isDefault) {
      const sourceExists = chart.states.some(
        (s) => s.id === transition.sourceStateId
      );
      if (!sourceExists) {
        const targetState = chart.states.find(
          (s) => s.id === transition.targetStateId
        );
        if (targetState) {
          const nodeWidth = targetState.size.width;
          const dotNode: DefaultTransitionNode = {
            id: transition.sourceStateId,
            type: 'defaultTransition',
            position: {
              x: targetState.position.x + nodeWidth / 2 - 8,
              y: targetState.position.y - 40,
            },
            ...(targetState.parentId
              ? { parentId: targetState.parentId, extent: 'parent' as const }
              : {}),
            data: { targetStateId: transition.targetStateId },
            style: { width: 16, height: 16 },
          };
          nodes.push(dotNode);
        }
      }
    }

    const edge: TransitionEdge = {
      id: transition.id,
      source: transition.sourceStateId,
      target: transition.targetStateId,
      sourceHandle: transition.sourceHandle || (transition.isDefault ? 'default-source' : undefined),
      targetHandle: transition.targetHandle || (transition.isDefault ? 'top-3' : undefined),
      type: 'transition',
      data: {
        transitionId: transition.id,
        label: transition.label,
        priority: transition.priority,
        isDefault: transition.isDefault,
        labelOffsetX: 0,
        labelOffsetY: 0,
      },
    };
    edges.push(edge);
  }

  if (chart.annotations) {
    for (const anno of chart.annotations) {
      const annotationNode: AnnotationNode = {
        id: anno.id,
        type: 'annotationNode',
        position: anno.position,
        data: {
          content: anno.content,
          color: anno.color,
          image: anno.image,
          fontSize: anno.fontSize ?? 14,
        },
        style: {
          width: anno.size.width,
          height: anno.size.height,
        },
      };
      nodes.push(annotationNode);
    }
  }

  return { nodes, edges };
}

// ─── System Serialization ───────────────────────────────────────

/**
 * Serialize the system canvas back into system blocks + wires
 * Updates positions/sizes from the canvas nodes, wires from edges
 */
export function serializeSystemCanvas(
  currentBlocks: SystemBlock[],
  currentWires: SystemWire[],
  nodes: CanvasNode[],
  edges: TransitionEdge[]
): { blocks: SystemBlock[]; wires: SystemWire[] } {
  const blocks = currentBlocks.map((block) => {
    const node = nodes.find((n) => n.id === block.id);
    if (!node) return block;
    return {
      ...block,
      position: node.position,
      size: {
        width: (node.style?.width as number) ?? block.size.width,
        height: (node.style?.height as number) ?? block.size.height,
      },
    };
  });

  // Serialize wire edges back to SystemWire data
  const wires: SystemWire[] = [];
  for (const edge of edges) {
    if (edge.type === 'systemWire' && edge.data) {
      const wireData = edge.data as unknown as { wireId: string };
      wires.push({
        id: wireData.wireId ?? edge.id,
        sourceBlockId: edge.source,
        sourcePortId: edge.sourceHandle ?? '',
        targetBlockId: edge.target,
        targetPortId: edge.targetHandle ?? '',
      });
    }
  }

  return { blocks, wires };
}

/**
 * Deserialize system blocks + wires into canvas nodes and edges
 */
export function deserializeSystemToCanvas(project: Project): {
  nodes: CanvasNode[];
  edges: TransitionEdge[];
} {
  const nodes: CanvasNode[] = [];
  const edges: TransitionEdge[] = [];

  for (const block of project.systemBlocks) {
    if (block.type === 'chart') {
      const chart = project.charts.find((c) => c.id === block.chartId);
      const chartNode: ChartBlockNode = {
        id: block.id,
        type: 'chartBlock',
        position: block.position,
        data: {
          chartId: block.chartId ?? '',
          chartName: chart?.name ?? block.name,
          ports: chart?.ports ?? [],
        },
        style: {
          width: block.size.width,
          height: block.size.height,
        },
      };
      nodes.push(chartNode);
    } else if (block.type === 'constant' || block.type === 'signalGenerator') {
      const sourceNode: SourceBlockNode = {
        id: block.id,
        type: 'sourceBlock',
        position: block.position,
        data: {
          blockType: block.type,
          name: block.name,
          config: { ...block.config },
        },
        style: {
          width: block.size.width,
          height: block.size.height,
        },
      };
      nodes.push(sourceNode);
    } else if (block.type === 'scope' || block.type === 'display') {
      const sinkNode: SinkBlockNode = {
        id: block.id,
        type: 'sinkBlock',
        position: block.position,
        data: {
          blockType: block.type,
          name: block.name,
          config: { ...block.config },
        },
        style: {
          width: block.size.width,
          height: block.size.height,
        },
      };
      nodes.push(sinkNode);
    }
  }

  // Deserialize system wires as edges
  for (const wire of project.systemWires) {
    const wireEdge: SystemWireEdge = {
      id: `wire-${wire.id}`,
      source: wire.sourceBlockId,
      target: wire.targetBlockId,
      sourceHandle: wire.sourcePortId || undefined,
      targetHandle: wire.targetPortId || undefined,
      type: 'systemWire',
      data: {
        wireId: wire.id,
      },
    };
    // Cast to TransitionEdge for canvas store compatibility
    edges.push(wireEdge as unknown as TransitionEdge);
  }

  return { nodes, edges };
}

// ─── Legacy Compat (wraps new functions) ────────────────────────

/**
 * @deprecated Use serializeCanvasToChart + serializeSystemCanvas instead.
 * Kept for backward compatibility during transition.
 */
export function serializeCanvasToProject(
  project: Project,
  nodes: CanvasNode[],
  edges: TransitionEdge[]
): Project {
  // This should not be called in the new architecture,
  // but if it is, we return the project as-is with updated timestamp
  return {
    ...project,
    updatedAt: new Date().toISOString(),
  };
}

import type { ASTNode } from './types';
import { parse, parseExpression } from './parser';
import { emitC, emitCStatement, emitCCondition, type CEmitOptions } from './c-emitter';
import { emitSCL, emitSCLStatement, emitSCLCondition, type SCLEmitOptions } from './scl-emitter';

/**
 * Translate a condition string to C.
 * Falls back to raw string if parsing fails.
 */
export function translateConditionToC(
  input: string,
  opts: CEmitOptions = {}
): string {
  if (!input.trim()) return '';
  const { node } = parseExpression(input);
  if (!node) return input; // fallback
  return emitCCondition(node, opts);
}

/**
 * Translate an action string (may contain multiple statements) to C.
 * Returns array of C statements.
 */
export function translateActionToC(
  input: string,
  opts: CEmitOptions = {}
): string[] {
  if (!input.trim()) return [];
  const { statements, errors } = parse(input);
  if (errors.length > 0 || statements.length === 0) return [input + ';']; // fallback
  return statements.map((s) => emitCStatement(s, opts));
}

/**
 * Translate a condition string to SCL.
 * Falls back to raw string if parsing fails.
 */
export function translateConditionToSCL(
  input: string,
  opts: SCLEmitOptions = {}
): string {
  if (!input.trim()) return '';
  const { node } = parseExpression(input);
  if (!node) return input; // fallback
  return emitSCLCondition(node, opts);
}

/**
 * Translate an action string (may contain multiple statements) to SCL.
 * Returns array of SCL statements.
 */
export function translateActionToSCL(
  input: string,
  opts: SCLEmitOptions = {}
): string[] {
  if (!input.trim()) return [];
  const { statements, errors } = parse(input);
  if (errors.length > 0 || statements.length === 0) return [input + ';']; // fallback
  return statements.map((s) => emitSCLStatement(s, opts));
}

/**
 * Check if any expression in a list uses temporal operators.
 * Used by generators to decide whether to add tick counter variables.
 */
export function usesTemporalLogic(expressions: string[]): boolean {
  for (const input of expressions) {
    if (!input.trim()) continue;
    const { statements } = parse(input);
    for (const stmt of statements) {
      if (hasTemporalNode(stmt)) return true;
    }
    // Also try as expression
    const { node } = parseExpression(input);
    if (node && hasTemporalNode(node)) return true;
  }
  return false;
}

function hasTemporalNode(node: ASTNode): boolean {
  switch (node.type) {
    case 'temporal':
    case 'elapsed':
      return true;
    case 'binary':
      return hasTemporalNode(node.left) || hasTemporalNode(node.right);
    case 'unary':
      return hasTemporalNode(node.operand);
    case 'call':
      return node.args.some(hasTemporalNode);
    case 'assignment':
      return hasTemporalNode(node.value);
    default:
      return false;
  }
}
